document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".toggle-password").forEach(e=>{e.addEventListener("click",()=>{const t=e.previousElementSibling,s=e.querySelector("i"),n="text"===t.type;t.type=n?"password":"text",s.classList.toggle("fa-eye"),s.classList.toggle("fa-eye-slash")})}),document.querySelectorAll(".social-btn").forEach(e=>{e.addEventListener("click",()=>{const t=e.innerHTML;e.disabled=!0,e.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> جارِ التحويل ...',setTimeout(()=>{e.innerHTML=t,e.disabled=!1},1500)})})});